            var publicProvider=(LayeredNavigationProvider)NavigationAdmission.CertifiedFlatProvider(new NavGeometry(3,new NavObstacle[0],1));var c=new NavClearanceProfile("ground",1,"ground",1,.25);var profile=new NavGraphProfile(new string('d',64),"distance",1,1);var limits=new NavGraphCompileLimits(2000,2000,10000);var arrival=new NavigationProfile();var publicMember=new NavArrivalMember(3,1,1,1,new NavLocation(new NavPoint(-1,0),NavLocation.FlatSurface),c,3,1,1,1,0,1,1,1,"HOLD");var source=new NavArrivalCandidateSource("proof-source",1,new NavLocation(new NavPoint(1,0),NavLocation.FlatSurface),new[]{new NavLocation(new NavPoint(1,0),NavLocation.FlatSurface)});var occupancy=new NavArrivalOccupancySnapshot(3,new NavArrivalOccupant[0]);var original=new NavArrivalInput("topology","profile",publicProvider,profile,arrival,limits,source,new[]{publicMember},occupancy,4096,null,true);
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var birth));var r=birth.OwnedReservation();var provider=LayeredNavigationProvider.CopyOwned(publicProvider,r);var meta=NavGraphMetadata.CopyOptionalUnowned(c,profile,limits,r);var ap=NavigationProfile.CopyOwned(arrival,r);var s=NavArrivalCandidateSource.CopyOwned(source,r);var o=NavArrivalOccupancySnapshot.CopyOwned(occupancy,new NavArrivalOccupant[0],r);var member=NavArrivalMember.CopyOwned(publicMember,meta.Clearance,r);var binding=NavArrivalWorkingBinding.CreateOwned(3,provider,meta.Profile,r);var input=NavArrivalInput.CopyOwned(original,provider,meta.Profile,ap,meta.Limits,s,new[]{member},o,new[]{binding},r);
