            var sameValueRequest=NavScheduledRequest.CreateOwned(provider,member.Clearance,binding.Profile,input.Limits,null,sub,4096,r,true);Assert.AreEqual(request.Subscription.StableKey,sameValueRequest.Subscription.StableKey);Assert.AreNotSame(request.Subscription,sameValueRequest.Subscription);Assert.AreEqual(proof.StableKey,new NavArrivalReachabilityProof(input,member,endpoint,sameValueRequest,route).StableKey);var invalidRequest=new Refusal(birth,int.MaxValue);Assert.Throws<ArgumentException>(()=>NavArrivalReachabilityProof.CreateOwned(input,member,endpoint,sameValueRequest,route,invalidRequest));Assert.Zero(invalidRequest.Calls);sameValueRequest.StorageRoot.ReleaseOwner();sameValueRequest=null;var wrongCost=NavTypedRoute.CopySubscriptionAndCreateOwned(request.Subscription,route.Legs,1,r);Assert.AreEqual(proof.StableKey,new NavArrivalReachabilityProof(input,member,endpoint,request,wrongCost).StableKey);var invalidCost=new Refusal(birth,int.MaxValue);Assert.Throws<ArgumentException>(()=>NavArrivalReachabilityProof.CreateOwned(input,member,endpoint,request,wrongCost,invalidCost));Assert.Zero(invalidCost.Calls);wrongCost.ReleaseOwner();wrongCost=null;byte[] proofBytes=CaptureGraph(hot,proof.StorageRoot);
