            byte[] Next(NavigationRetentionBudget budget,NavArrivalProposal proposal,out long physical){Assert.True(budget.TryOpenScope(NavigationPreparationKind.Projection,1,20,out var operation));var next=NavArrivalProposal.CreateOwned(proposal.Member,proposal.Endpoint,proposal.Route,proposal.Proof,operation.OwnedReservation());operation.Attach(next.StorageRoot);operation.Commit(next.StorageRoot,_=>{});var output=CaptureGraph(budget,next.StorageRoot);physical=Unique(next.StorageRoot);next.StorageRoot.ReleaseOwner();return output;}
            byte[] expected=Next(hot,first,out long expectedCharge);bundle.Release();bundle=null;proof=null;first=null;second=null;input=null;request=null;route=null;member=null;provider=null;meta=null;ap=null;s=null;o=null;binding=null;original=null;publicProvider=null;publicMember=null;source=null;occupancy=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavRetainedArray<NavOwnedStorage>)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});var pr=(NavArrivalReachabilityProof)((NavDeclarationStorage)restored[0]).Facade;var a=(NavArrivalProposal)((NavDeclarationStorage)restored[1]).Facade;var b=(NavArrivalProposal)((NavDeclarationStorage)restored[2]).Facade;var i=(NavArrivalInput)((NavDeclarationStorage)restored[3]).Facade;var q=(NavScheduledRequest)((NavDeclarationStorage)restored[4]).Facade;var rt=(NavTypedRoute)restored[5];Assert.AreSame(a.Proof,b.Proof);Assert.AreSame(pr,a.Proof);Assert.AreSame(a.Member,i.Members[0]);Assert.AreSame(a.Route,pr.Route);Assert.AreSame(rt,a.Route);Assert.AreSame(q.Subscription,pr.Subscription);Assert.AreSame(rt.Subscription,q.Subscription);Assert.AreSame(q.GraphKey,pr.GraphBinding);Assert.AreSame(i.TopologyIdentity,pr.TopologyIdentity);Assert.AreSame(i.Occupancy.StableKey,pr.OccupancyBinding);Assert.AreSame(ownEndpoint?pr.StorageRoot:i.Source.StorageRoot,pr.Endpoint.NameReference.Owner);Assert.AreEqual(ownEndpoint?NavNameRole.ArrivalProofEndpointSurface:NavNameRole.ArrivalSourceCandidateSurface,pr.Endpoint.NameReference.Role);Assert.AreSame(pr.Endpoint.NameReference.Owner,a.Endpoint.NameReference.Owner);Assert.True(pr.ValidateAgainst(i,a.Member,a.Endpoint));Assert.AreEqual(charge,cold.PhysicalBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));CollectionAssert.AreEqual(expected,Next(cold,a,out long actualCharge));Assert.AreEqual(expectedCharge,actualCharge);
            foreach(bool proposal in new[]{false,true}){NavOwnedStorage Born(INavStorageReservation reservation)=>proposal?NavArrivalProposal.CreateOwned(a.Member,a.Endpoint,rt,pr,reservation).StorageRoot:NavArrivalReachabilityProof.CreateOwned(i,a.Member,pr.Endpoint,q,rt,reservation).StorageRoot;Assert.True(cold.TryOpenScope(NavigationPreparationKind.Projection,1,30,out var trialScope));var counter=new Refusal(trialScope,int.MaxValue);var born=Born(counter);trialScope.Attach(born);int calls=counter.Calls;trialScope.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);for(int nth=1;nth<=calls;nth++){Assert.True(cold.TryOpenScope(NavigationPreparationKind.Projection,1,30+nth,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Born(refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));}var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Projection,1,1,out var rejected));Assert.Throws<ArgumentException>(()=>Born(rejected.OwnedReservation()));Assert.Zero(foreign.PhysicalBytes);Assert.AreEqual(NavigationRetentionBudget.ScopeBytes,foreign.HeldBytes);rejected.Discard();}
            var pin=a.StorageRoot;pin.Retain();restored.Release();restored=null;a=null;b=null;pr=null;i=null;q=null;rt=null;Assert.AreEqual(Unique(pin),cold.PhysicalBytes);var pinned=(NavArrivalProposal)((NavDeclarationStorage)pin).Facade;Assert.True(pinned.Proof.ValidateAgainst((NavArrivalInput)((NavDeclarationStorage)((NavDeclarationStorage)pinned.Proof.StorageRoot).First).Facade,pinned.Member,pinned.Endpoint));pin.Release();pin=null;pinned=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            byte[] malformed=(byte[])proofBytes.Clone();malformed[malformed.Length-2]=255;malformed[malformed.Length-1]=255;var corrupt=new NavigationRetentionBudget();Assert.True(corrupt.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var corruptScope));Assert.Throws<ArgumentException>(()=>Decode(malformed,corruptScope.OwnedReservation()));corruptScope.Discard();Assert.Zero(corrupt.PhysicalBytes);Assert.Zero(corrupt.HeldBytes);Assert.Zero(corrupt.ActiveScopes);
            var counted=new NavigationRetentionBudget();Assert.True(counted.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var scope));var all=new Refusal(scope,int.MaxValue);var trial=Decode(bytes,all);scope.Attach(trial);int allocations=all.Calls;scope.Discard();Assert.Zero(counted.PhysicalBytes);for(int nth=1;nth<=allocations;nth++){var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);Assert.Zero(bad.ActiveScopes);}
